#include "FileStuff.h"#include "BMP.h"long SwapEndian ( long );OSErr readBMP ( Str255 thePictureFileName, long &theExpectedWidth, long &theExpectedHeight, Myth256Palette  *thePalette, char *theBits ){//----------------------------------vars--------------------------------------------------	OSErr		theError;	FSSpec		thePictureFSSpec;	short		thePictureFileRef;		long		theWidth, theHeight, theSize, theBMPWidth;	long		thePadLength, theBMPSize, theBISize;	long 		bitOffset, paletteLength;	picturePalette thePicturePalette[256];	int i, theMark;	//----------------------------------vars--------------------------------------------------// the texture plug	theError = FSMakeFSSpec (0L, 0L, thePictureFileName, &thePictureFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePictureFSSpec, fsCurPerm, &thePictureFileRef );	if ( theError != noErr )		return theError;// Get the offset to the bits and palette length	FileSeek ( thePictureFileRef, 10L );	FileRead (&bitOffset, 4L, thePictureFileRef);	bitOffset = SwapEndian ( bitOffset );	paletteLength = bitOffset - 54;	if ( paletteLength > (long) sizeof(thePicturePalette) )		paletteLength = (long) sizeof(thePicturePalette);	FileSeek ( thePictureFileRef, 14L );	FileRead ( &theSize, 4L, thePictureFileRef );	theBISize = SwapEndian( theSize ) + 14;			// bitmap header + bm info size;	FileSeek ( thePictureFileRef, 18L );	FileRead ( &theWidth, 4L, thePictureFileRef );	theWidth = SwapEndian( theWidth );	FileSeek ( thePictureFileRef, 22L );	FileRead ( &theHeight, 4L, thePictureFileRef );	theHeight = SwapEndian( theHeight );	if ( theWidth != theExpectedWidth || theHeight != theExpectedHeight){		ParamText( "\pWrong size graphic file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		FSClose ( thePictureFileRef );		return -1;	}	theExpectedWidth = theWidth;	theExpectedHeight = theHeight;	thePadLength = 4 - (theWidth % 4);	if ( thePadLength == 4 )		thePadLength = 0;	theBMPWidth = theWidth + thePadLength;	theBMPSize = theBMPWidth * theHeight;	theSize = theWidth * theHeight;	if ( thePalette != nil ){		FileSeek ( thePictureFileRef, theBISize );		FileRead (&thePicturePalette, paletteLength, thePictureFileRef);		// Initialize the palette		for (i = 0; i < 256; i++){			thePalette->color[i].blue = 0;			thePalette->color[i].green = 0;			thePalette->color[i].red = 0;		}		for (i = 0; i < paletteLength / 4; i++){			thePalette->color[i].blue = thePicturePalette[i].blue;			thePalette->color[i].green = thePicturePalette[i].green;			thePalette->color[i].red = thePicturePalette[i].red;		}	}	FileSeek ( thePictureFileRef, bitOffset );	theMark = theSize - theWidth;	for( i = theBMPSize - theBMPWidth; i >= 0; i -= theBMPWidth ){		FileRead ( &theBits[theMark], theWidth, thePictureFileRef );		SetFPos ( thePictureFileRef, fsFromMark, (long) thePadLength );		theMark -= theWidth;	}	FSClose ( thePictureFileRef );	return 0;}